"""The former heuristic regression corpus now verifies verbatim public records."""
import pytest
from build import redact as R

TEXTS = ['Spoke with Mr. Sacks about the lateral', 'Mrs Jane Doe reported sewage in the yard', 'Called in by resident (Joe Romenelli)', 'Customer, Eric Kotarba, called with sewage in the basement.', 'Received a call from Ed Dubois, owner of house 45 Robbins Ave', 'Cathy, homeowner of 69 Dover Rd, called', 'Recieved call from Nancy Brown at 274 Morningside Drive West', 'Tim Lee 238 Scott street (landlord)', 'call from Simomne Corriveau at 96 Mercier Avenue', 'any questions please call Dan Gregory at [phone removed] thanks', 'left message with Iliana Raffa at [phone removed]', 'Complaint from Jose Acosta', 'Treatment plant operator Joe Barrios arrived at the plant', 'Notified by Robert Britain of the Town of Orange CT', 'per conversation with Nicole G. - Hurricane Dike Station', 'SPOKE WITH ROBERT SACKS REGARDING SEWER BACKUP', 'Bypass at Fort Point Channel near Boston Post Rd and Main Street', 'CSO 16 CONCORD AVE FRED MOLD PARK', '605 Baldwin Street, Francis Xavier plaza apartments utilizing dye testing', 'Sewer Main, 38 Patrick Flood Road Farmington CT', 'Manhole, Nathan Hale road', 'Martin Luther King Jr Blvd manhole overflowed', 'When the contractors Green Mountain Pipe turned on their pump a seal was missed', 'Bunker Hill residents reported odors', '45 Oak Dr. Smith said', 'Town of Orange WPCA notified; overflow reached the Charles River and Burr Creek', 'Huntington Road and Vernon Street regulator; Greater New Haven WPCA crew responded', 'Excessive Flows - Storm Event', 'Department received call from American Rooter about the lateral', 'Call came in for a backup located in front of Apex Pharmacy located at 2380 Dixwell Ave, Hamden', 'The rest of the Grit was shoveled up by the crew.', 'Case was assigned to Inspector [name removed] on 07/17/2025.', 'https://portal.ct.gov/Robert Sacks/report.pdf', 'PERSON REPORTING: Dan Quillfeather TYPE OF PROBLEM: Manhole', 'Contact at Scene: Dan Quillfeather; Telephone No.: [phone removed]', 'Referred to Dan Quillfeather with the local office', 'Land belonging to Dan Quillfeather', 'Caller requests a callback from RHMO Dan Quillfeather in reference to this', 'A call was placed to the complaintant, Dan Quillfeather, who stated there was no odor', 'Owned by his niece Dan Quillfeather who lives down the road', 'Zorbel Quillfeather, Chief Operator at the plant, provided notice', 'Zorbel Quillfeather (Director of Public Works) called back', 'Zorbel Quillfeather, Administrative Assistant at the plant, was contacted', 'Mayor Zorbel Quillfeather signed the notice', 'Dispatcher Zorbel Quillfeather reported a septic overflow', 'On June 5, 2026, Zorbel Quillfeather with the town of Wise provided email notification', 'On 6/5/2026 at 10:15 AM, Zorbel Quillfeather reported an overflow', 'Dan Quillfeather, with the Lee County PSA, provided email notification', 'Dan arrived on scene at 5:20 pm and informed the owners', 'Dan with the Lee County Authority advised that the pump failed', 'Per Dan Quillfeather the pump failed; Dan went home and Quillfeather stayed', 'Staff engaged our oncall contractor, Blorvex Civil, and our oncall consultant, Hazen for assistance', 'Valley St., Oldtown Road, Quillfeather Stret, N. Mechanic Street, Franklin Street', 'Blockage from an isolation plug lost by Blorvex Bros - owner [name removed]', 'Per [name removed] the pump failed on Dan Street and near Prince Dan Road', 'Dan Street and Dan Road manholes overflowed', 'On June 5, 2026, the plant reported an overflow']

@pytest.mark.parametrize('text', TEXTS)
def test_public_records_preserve_names_contacts_places_and_source_wording(text, tmp_path, monkeypatch):
    monkeypatch.setattr(R, 'blocklist', lambda *a: pytest.fail('retired list was accessed'))
    record = {'event_id': 'source:1', 'source_id': 'source', 'raw': {'note': text}, 'advice_text': text}
    assert R.redact_events([record], tmp_path) == [record]
    assert R.redactor_for([record], tmp_path).note(text) == text


def test_export_has_no_default_redaction_or_blocklist_phase():
    import inspect
    from export import build
    code = inspect.getsource(build.export)
    assert 'redact_events(' not in code and 'blocklist' not in code
    assert 'removals.publish(' in code and 'removals.enforce(' in code
